'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('ko-KR',{maximumFractionDigits:1});
const short=n=>n.replace('등학교','').replace('여자','여');
const KEY='bucheon-compass-v1';
const defaults={gender:'female',origin:'',distance:true,interests:['curriculum','commute'],wishlist:[],notes:{},times:{},compare:[],schoolSort:'name'};
let prefs;try{prefs={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{prefs={...defaults}}
let data,view='schools',query='',detailSchool=null,detailTab='overview',docCategory='',docId=null,docQuery='',docPage=0,grade=1,subjectSearch='',simMale=100,simFemale=100,simSplit=50;
const docCache=new Map();let docGeneration=0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(prefs))}catch{toast('브라우저 저장 공간을 사용할 수 없습니다. 백업 파일을 내려받아 주세요.')}$('#navCount').textContent=prefs.wishlist.length}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
const school=id=>data.schools.find(s=>s.id===Number(id));
const eligible=s=>prefs.gender!=='male'||!s.girls;
const origin=()=>data.middles.find(x=>x.name===prefs.origin);
function dist(s){let o=origin();if(!o?.lat||!s.lat)return null;let R=6371,rad=x=>x*Math.PI/180,a=Math.sin(rad(s.lat-o.lat)/2)**2+Math.cos(rad(o.lat))*Math.cos(rad(s.lat))*Math.sin(rad(s.lng-o.lng)/2)**2;return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
function distanceText(s){let d=dist(s);return prefs.distance&&d!==null?`직선 ${d.toFixed(1)}km`:'거리 기준 미설정'}
function route(s){let o=origin();return o?.lat?`https://map.kakao.com/link/by/traffic/${encodeURIComponent(o.name)},${o.lat},${o.lng}/${encodeURIComponent(s.name)},${s.lat},${s.lng}`:`https://map.kakao.com/link/to/${encodeURIComponent(s.name)},${s.lat},${s.lng}`}
const external=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function graduate(s){return s.graduates.find(x=>x.gender==='합계')}
const rate=(n,d)=>d?`${(100*n/d).toFixed(1)}%`:'—';
function setView(v){view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){if(!data)return;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#main').innerHTML=({schools:schoolsView,wishlist:wishlistView,demand:demandView,guide:guideView}[view]||schoolsView)();save();compareBar()}
function sidebar(){return `<aside class="sidebar"><h2>학교 찾기 설정</h2><div class="formgrid"><div><span class="label">학생 성별</span><div class="segmented"><button data-gender="female" class="${prefs.gender==='female'?'on':''}">여학생</button><button data-gender="male" class="${prefs.gender==='male'?'on':''}">남학생</button></div></div><div><label class="label" for="origin">다니는 중학교</label><select id="origin"><option value="">중학교를 선택해 주세요</option>${data.middles.map(m=>`<option ${prefs.origin===m.name?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></div><label class="check"><input id="distance" type="checkbox" ${prefs.distance?'checked':''}>학교까지 거리 보기</label><p class="hint">중학교 위치에서 잰 직선거리입니다.<br>실제 통학시간은 길찾기로 확인해 기록할 수 있어요.</p><span class="label">먼저 보고 싶은 정보</span><div class="chips">${[['commute','통학'],['curriculum','선택과목'],['assessment','평가 방식'],['achievement','성취도'],['graduates','졸업 후 진학']].map(([id,label])=>`<button class="chip ${prefs.interests.includes(id)?'on':''}" data-interest="${id}" aria-pressed="${prefs.interests.includes(id)}">${label}</button>`).join('')}</div><p class="hint">여러 개 선택할 수 있어요.<br></p><div class="divider"><div class="mini"><span>↗</span><div><b>관심 학교를 담아 보세요</b><span>지망표에서 순서를 정하고 메모를 남겨 보세요.</span></div></div><button class="textbtn" data-go="wishlist">내 지망표 보기 →</button></div></aside>`}
function card(s){let delta=s.quota-s.quota2026,a=s.admissions.find(x=>x.year===2026),added=prefs.wishlist.includes(s.id);let links=[['curriculum','선택과목'],['assessment','평가 방식'],['achievement','성취도'],['graduates','졸업 후 진로']].filter(([key])=>prefs.interests.includes(key));return `<article class="schoolcard"><div class="school-title-row"><h3><button data-detail="${s.id}">${esc(short(s.name))}</button></h3><label class="comparecheck"><input type="checkbox" data-compare="${s.id}" ${prefs.compare.includes(s.id)?'checked':''}>비교</label></div><div class="badges"><span class="badge">${s.girls?'여고':'남녀공학'}</span><span class="badge">${esc(s.ownership)}</span>${s.name==='수주고등학교'?'<span class="badge warm">자율형 공립고</span>':''}${prefs.distance&&origin()?`<span class="badge distance">${distanceText(s)}</span>`:''}</div><p class="addr">${esc(s.address.replace('경기도 부천시 ',''))}</p><div class="metrics"><div><small>2027 모집정원</small><strong>${fmt(s.quota)}<em>명</em></strong></div><div><small>2026 모집정원</small><strong>${fmt(s.quota2026)}<em>명</em></strong></div></div><p class="quota-change">지난해와 비교 <b>${delta===0?'변동 없음':fmt(Math.abs(delta))+'명 '+(delta>0?'증가':'감소')}</b></p><div class="school-shortcuts">${links.map(([key,label])=>`<button data-detail="${s.id}" data-detailtab="${key}">${label} ›</button>`).join('')}</div><details class="card-extra"><summary>지난해 실제 입학생</summary><p>2026학년도 ${fmt(a?.total||0)}명 · 모집정원과는 다를 수 있어요.</p></details><div class="cardactions"><button class="textbtn" data-detail="${s.id}">학교 정보 보기</button><button class="add ${added?'added':''}" data-add="${s.id}">${added?'✓ 추가됨':'지망표에 추가'}</button></div></article>`}
function schoolsView(){let ss=data.schools.filter(eligible).filter(s=>(s.name+s.address+s.achievement.map(x=>x.subject).join(' ')).includes(query));if(prefs.schoolSort==='distance'&&prefs.distance&&origin())ss.sort((a,b)=>(dist(a)??100)-(dist(b)??100));if(prefs.schoolSort==='change')ss.sort((a,b)=>(b.quota-b.quota2026)-(a.quota-a.quota2026));
return `<section class="hero simple-hero"><div><p class="eyebrow">2027학년도 · 부천 일반고</p><h1>어느 고등학교에 갈까요?</h1><p>학교를 비교하고, 가고 싶은 순서대로 정리해 보세요.</p><div class="use-steps" aria-label="이용 순서"><span><b>1</b> 학교 살펴보기</span><i>›</i><span><b>2</b> 관심 학교 비교</span><i>›</i><span><b>3</b> 지망표 저장</span></div></div></section><div class="workspace">${sidebar()}<section aria-label="학교 목록"><div class="toolbar"><h2>학교 목록 <span class="muted">${ss.length}</span></h2><div class="tools"><input type="search" id="schoolSearch" aria-label="학교명·주소·공시 과목 검색" placeholder="학교 이름·동네·과목 검색" value="${esc(query)}"><select id="schoolSort" aria-label="학교 정렬"><option value="name" ${prefs.schoolSort==='name'?'selected':''}>이름순</option><option value="distance" ${prefs.schoolSort==='distance'?'selected':''}>거리 가까운 순</option><option value="change" ${prefs.schoolSort==='change'?'selected':''}>정원 많이 늘어난 순</option></select></div></div><p class="statusline">${prefs.gender==='male'?'남학생이 지망할 수 있는 남녀공학 20개교':'여학생이 지망할 수 있는 22개교'} · 비교할 학교를 2~4곳 선택해 보세요.</p><div class="grid">${ss.map(card).join('')}</div>${!ss.length?'<div class="empty">검색 결과가 없습니다. 다른 학교명이나 동네를 입력해 주세요.</div>':''}</section></div>`}
function toggleAdd(id){let s=school(id);if(!eligible(s)){toast('남학생은 여학교를 지망할 수 없습니다.');return}if(prefs.wishlist.includes(id))prefs.wishlist=prefs.wishlist.filter(x=>x!==id);else prefs.wishlist.push(id);save();if(view==='wishlist'||view==='schools')render();if($('#modal').open&&detailSchool!==null)openDetail(detailSchool,detailTab);toast(prefs.wishlist.includes(id)?`${short(s.name)}를 지망표에 담았습니다.`:'지망표에서 제외했습니다.')}
function compareBar(){$('#comparebar').hidden=!prefs.compare.length;$('#compareNames').textContent=prefs.compare.map(id=>short(school(id).name)).join(' · ');$('#compareOpen').disabled=prefs.compare.length<2;$('#compareOpen').textContent=prefs.compare.length<2?'학교 1곳 더 선택':`${prefs.compare.length}개 학교 비교`}
function wishlistView(){let count=prefs.gender==='male'?20:22,chosen=prefs.wishlist.map(school).filter(Boolean);return `<div class="page"><h1>내 지망표</h1><p class="intro">가고 싶은 순서대로 정리하고, 이유를 메모해 보세요.</p><div class="panels"><section><div class="row"><h2 style="font-size:18px">담아 둔 학교 ${chosen.length}개교</h2><button class="textbtn" data-go="schools">학교 추가</button></div>${chosen.length?`<ol class="ranklist">${chosen.map((s,i)=>`<li class="rankitem" draggable="true" data-rank="${s.id}"><span class="ranknum rankgrip" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><strong><button class="inline-link" data-detail="${s.id}">${esc(short(s.name))}</button></strong><small>${s.girls?'여학교':'남녀공학'} · ${distanceText(s)}${prefs.times[s.id]?` · 직접 확인 ${esc(prefs.times[s.id])}분`:''}</small><textarea data-note="${s.id}" aria-label="${esc(short(s.name))} 지망 이유" placeholder="좋은 점이나 더 알아볼 점을 적어 보세요">${esc(prefs.notes[s.id]||'')}</textarea></div><div class="controls"><button class="iconbtn" data-move="${s.id},-1" ${i===0?'disabled':''} aria-label="${esc(short(s.name))} 순위 올리기">↑</button><button class="iconbtn" data-move="${s.id},1" ${i===chosen.length-1?'disabled':''} aria-label="${esc(short(s.name))} 순위 내리기">↓</button><button class="iconbtn" data-remove="${s.id}" aria-label="${esc(short(s.name))} 지망표에서 삭제">×</button></div></li>`).join('')}</ol>`:`<div class="empty"><h3>가고 싶은 학교부터 추가해 보세요</h3><p>학교를 추가한 뒤 위아래 버튼으로 순서를 바꿀 수 있어요.</p><button class="primary" data-go="schools">학교 찾아보기 →</button></div>`}</section><aside><div class="panel"><h2>지망 순서 정리</h2><div class="big">${chosen.length}<span class="muted" style="font-size:18px"> / ${count}</span></div><div class="progress"><div style="width:${chosen.length/count*100}%"></div></div><p>${chosen.length===count?'모든 학교를 담았습니다. 순서를 다시 한 번 확인하세요.':`지금은 관심 있는 학교부터 담아도 괜찮아요. 원서를 쓸 때는 ${count}개 학교의 순서를 모두 정해야 해요.`}</p><button class="outline" id="fillRemaining">남은 이름순으로 추가</button><p class="hint">추가된 순서는 이름순이에요. 원하는 순서로 바꿔 주세요.</p><div class="notice">이 지망표는 검토용이에요. 실제 원서는 학교의 안내에 따라 제출해 주세요.</div><div class="actions"><button class="primary" id="downloadList">지망표 CSV 저장</button><button class="outline" id="printList">인쇄</button></div></div><div class="panel"><h2>기록 백업</h2><p>지망 순서와 메모는 이 브라우저에 저장됩니다. 다른 기기에서는 백업 파일을 불러와 주세요.</p><div class="actions"><button class="outline small" id="backup">백업 저장</button><button class="outline small" id="restore">백업 불러오기</button></div><p class="hint">이름·연락처·집 주소는 수집하지 않습니다.</p></div></aside></div></div>`}
function baseline(){let a=data.admissions.filter(x=>x.year===2026),p25=data.population['2025'],p26=data.population['2026'];let m=a.reduce((n,x)=>n+x.male,0),f=a.reduce((n,x)=>n+x.female,0);return {m,f,pm:m/p25.male*p26.male,pf:f/p25.female*p26.female}}
function demandView(){let b=baseline(),p=data.population;return `<div class="page"><h1>2027학년도 정원과 예상 인원</h1><p class="intro">지난해 입학생과 올해 중3 학생 수로 입학 인원을 가늠해 봅니다. 실제 지원 결과는 아니에요.</p><div class="three"><div class="metricbox"><small>2026년 부천 중3 학생</small><strong>${fmt(p['2026'].total)}명</strong><p>남 ${fmt(p['2026'].male)} · 여 ${fmt(p['2026'].female)} / 2025년 ${fmt(p['2025'].total)}명</p></div><div class="metricbox"><small>2026학년도 일반고 실제 입학생</small><strong>4,979명</strong><p>남 2,473 · 여 2,506 / 당시 부천고 포함 23개교</p></div><div class="metricbox"><small>2027학년도 부천 일반고 모집정원</small><strong>4,836명</strong><p>남녀공학 4,428 · 여학교 408 / 22개교</p></div></div><div class="panels" style="margin-top:25px"><section class="panel"><h2>예상 인원을 바꿔 보기</h2><p>2026 실제 입학생 ÷ 2025년 중3 학생 × 2026년 중3 학생으로 기준값을 구했습니다. 남녀별로 각각 계산합니다.</p><div class="sliderrow"><div class="row"><label for="simMale">남학생 예상 인원 조정</label><b id="maleFactor">${simMale}%</b></div><input id="simMale" type="range" min="85" max="115" step="1" value="${simMale}"></div><div class="sliderrow"><div class="row"><label for="simFemale">여학생 예상 인원 조정</label><b id="femaleFactor">${simFemale}%</b></div><input id="simFemale" type="range" min="85" max="115" step="1" value="${simFemale}"></div><div id="simOutput"></div><div class="notice">이 비율은 부천 중학생만의 일반고 진학률이 아닙니다. 지역 간 유출입, 검정고시·이전 졸업자 등이 섞인 지역 입학 규모 비율입니다. 학교별 합격·배정 확률을 뜻하지 않습니다.</div><h3>남녀별 정원 가정</h3><p>남녀공학의 실제 남녀 배정 인원은 지원 상황 등에 따라 산출됩니다. 아래 비율은 사용자가 바꾸는 가정입니다.</p><div class="sliderrow"><div class="row"><label for="simSplit">남녀공학의 남학생 비율 가정</label><b id="splitLabel">${simSplit}%</b></div><input id="simSplit" type="range" min="40" max="60" step="1" value="${simSplit}"></div><div id="sexOutput"></div><button class="textbtn" id="resetSim">처음 값으로 되돌리기</button></section><section><div class="panel"><h2>정원은 어떻게 달라졌나요?</h2><div class="quotachart"><span>2026학년도</span><div class="bar" style="width:80%"></div><small>5,037명</small></div><div class="quotachart"><span>2027학년도</span><div class="bar" style="width:76.8%;background:#bc805d"></div><small>4,836명</small></div><p>전체 −201명. 부천고의 과학고 전환으로 일반고 168명이 제외되었고, 나머지 22개교의 합계는 33명 감소했습니다.</p><p class="hint">2026 정원은 당시 안내자료의 모집정원, 2027 학교별 모집정원은 경기도교육청 신입생 전형계획 24쪽 기준입니다. 실제 입학생 수와 모집정원은 다를 수 있습니다.</p></div><div class="panel"><h2>계산에 쓰인 원자료</h2><table><thead><tr><th>구분</th><th class="num">남</th><th class="num">여</th></tr></thead><tbody><tr><td>2025년 중3</td><td class="num">${fmt(p['2025'].male)}</td><td class="num">${fmt(p['2025'].female)}</td></tr><tr><td>2026년 중3</td><td class="num">${fmt(p['2026'].male)}</td><td class="num">${fmt(p['2026'].female)}</td></tr><tr><td>2026 실제 입학생</td><td class="num">${fmt(b.m)}</td><td class="num">${fmt(b.f)}</td></tr><tr><td>기준 비율</td><td class="num">${rate(b.m,p['2025'].male)}</td><td class="num">${rate(b.f,p['2025'].female)}</td></tr></tbody></table><p class="hint">중3: 2025·2026년 학교알리미 자료 및 다운로드 엑셀 대조. 실제 입학생: 학교알리미 2026 공시 23개교 합계.</p></div></section></div><section class="panel"><h2>학교별 정원 변화</h2><div class="tablewrap"><table><thead><tr><th>학교</th><th class="num">2026 모집정원</th><th class="num">2026 실제 입학생</th><th class="num">2027 모집정원</th><th class="num">모집정원 증감</th></tr></thead><tbody>${data.schools.map(s=>`<tr><td><button class="inline-link" data-detail="${s.id}">${esc(short(s.name))}</button></td><td class="num">${s.quota2026}</td><td class="num">${s.admissions.find(x=>x.year===2026).total}</td><td class="num">${s.quota}</td><td class="num">${s.quota-s.quota2026>0?'+':''}${s.quota-s.quota2026}</td></tr>`).join('')}<tr><td>부천고 · 일반고에서 제외</td><td class="num">168</td><td class="num">${data.admissions.find(x=>x.school==='부천고등학교'&&x.year===2026).total}</td><td class="num">0</td><td class="num">−168</td></tr></tbody></table></div></section><p class="sourcefoot">출처: 제공받은 2025·2026년 중학교 학생수 엑셀, 학교알리미 입학생 현황, 2026학년도 부일중 안내문, 2027학년도 모집 전형 공고, 2027학년도 신입생 전형계획(2026년 10월).</p></div>`}
function renderSim(){if(view!=='demand')return;let b=baseline(),m=b.pm*simMale/100,f=b.pf*simFemale/100,t=m+f,d=t-4836,mc=4428*simSplit/100,fc=4836-mc;$('#maleFactor').textContent=simMale+'%';$('#femaleFactor').textContent=simFemale+'%';$('#splitLabel').textContent=simSplit+'%';$('#simOutput').innerHTML=`<div class="sim-output"><small>예상 입학 인원</small><div><strong>${fmt(Math.round(t))}명</strong> <span class="muted"> / 정원 4,836명</span></div><p>남 ${fmt(Math.round(m))}명 · 여 ${fmt(Math.round(f))}명</p><b>정원 대비 ${fmt(Math.round(Math.abs(d)))}명 ${d>0?'많음':'적음'}</b></div>`;$('#sexOutput').innerHTML=`<table><thead><tr><th>구분</th><th class="num">예상 수요</th><th class="num">가정한 정원</th><th class="num">정원과 차이</th></tr></thead><tbody><tr><td>남</td><td class="num">${fmt(Math.round(m))}</td><td class="num">${fmt(Math.round(mc))}</td><td class="num">${fmt(Math.round(m-mc))}</td></tr><tr><td>여</td><td class="num">${fmt(Math.round(f))}</td><td class="num">${fmt(Math.round(fc))}</td><td class="num">${fmt(Math.round(f-fc))}</td></tr></tbody></table><p class="hint">여학생 가정한 정원 = 공학의 여학생 몫 + 여학교 408명. 실제 성별 배정 정원과 다를 수 있습니다.</p>`}
function guideView(){return `<div class="page"><h1>지원 일정과 배정 방법</h1><p class="intro">2027학년도 경기도교육청 공고와 학생 배정 방안에서 부천 관련 내용을 정리했습니다.</p><div class="panels"><section><div class="panel"><h2>부천 고등학교, 이렇게 배정돼요</h2><div class="step"><span>1</span><div><b>학군 모집정원만큼 선발</b><p>중학교 내신성적 200점으로 배정 대상자를 선발합니다. 특정 학교의 내신 합격선을 뜻하지 않습니다.</p></div></div><div class="step"><span>2</span><div><b>전체 학교의 지망 순위 작성</b><p>남학생은 공학 20개교, 여학생은 공학 20개교와 여학교 2개교, 총 22개교의 순위를 작성합니다.</p></div></div><div class="step"><span>3</span><div><b>지망 순위를 반영해 추첨 배정</b><p>학교별 1지망부터 충원하고, 자리가 남으면 다음 지망 순위로 넘어갑니다. 지망자가 배정 인원을 넘으면 추첨합니다.</p></div></div><div class="notice info">부천은 구역내 2단계 배정이 없습니다. 가까운 학교부터 자동 배정되는 방식도 아닙니다. 이 앱의 거리 정렬은 학교 선택을 돕는 참고 기능입니다.</div><p>학교별 배정 인원 = 모집정원 × 학군별 지원율(선배정자 포함). 남녀공학은 남녀별 인원을 산출하여 배정합니다.</p></div><div class="panel"><h2>지원 자격·별도 신청</h2><ul class="bullets"><li>경기도 소재 중학교 졸업예정자, 경기도 거주 중학교 졸업자·동등 학력 인정자 등이 대상입니다.</li><li>일부 자격의 거주 요건은 원서접수일 현재 전 가족의 주민등록과 실제 거주를 기준으로 합니다. 상세 자격은 공식 공고로 확인해야 합니다.</li><li>2027학년도 전기학교 합격자는 지원할 수 없습니다.</li><li>외고·국제고·자사고 동시지원자는 일반고를 2지망부터 작성하는 별도 방식입니다. 이 앱의 지망표는 일반고 내부 순서 검토용입니다.</li><li>체육특기자·지체장애인 등의 선배정, 쌍둥이·세 자녀 이상 동일교 배정은 각각 조건과 신청 절차를 확인하세요.</li><li>부천고는 2027년 3월 과학고 전환으로 일반고 지망 대상에서 제외됩니다. 수주고는 자율형 공립고입니다.</li></ul></div></section><aside><div class="panel"><h2>2027학년도 주요 일정</h2><div class="timeline"><section><small>2026. 12. 4. ~ 12. 10.</small><b>원서 접수</b><p>접수시간 09:00~17:00<br>마감 12월 10일 17:00</p></section><section><small>2027. 1. 6.</small><b>배정 대상자 발표</b></section><section><small>2027. 1. 22.</small><b>배정 학교 발표</b></section><section><small>2027. 1. 25. ~ 1. 27.</small><b>배정 학교 등록</b></section></div><p class="hint">출처: 2026.9.3. 공고 제2026-1271호. 변경 공고가 있을 수 있으므로 원서 접수 전 확인하세요.</p><a class="primary" style="display:inline-block;text-decoration:none" href="admissions-2027.pdf" target="_blank">모집 공고 보기 ↗</a></div><div class="panel"><h2>공식 자료 보기</h2><div class="doclist"><a class="doclink" href="allocation-2027.pdf" target="_blank">2027 학생 배정 방안 · 부천 37~39쪽 <span>↗</span></a><a class="doclink" href="admissions-2027.pdf" target="_blank">2027 모집 전형 공고 <span>↗</span></a><a class="doclink" href="quota-2026-notice.pdf" target="_blank">2026 모집정원 비교 기준 안내문 <span>↗</span></a><a class="doclink" href="school-data.xlsx" download>22개교 공개자료 통합 엑셀 <span>↓</span></a>${external('https://www.schoolinfo.go.kr/','학교알리미','doclink')}</div></div></aside></div><div class="panel"><h2>자료별 기준과 출처</h2><div class="helpgrid"><div><b>교육과정 · 선택과목</b><p>2026년 교육과정 원문과 실제 성취도 공시 과목을 보여줍니다. 2027학년도 신입생 확정 편제와 실제 개설 조건은 추가 확인이 필요합니다.</p></div><div><b>평가계획</b><p>2026학년도 1학년 국어·수학·영어의 지필평가·수행평가 비율을 보여줍니다. 자세한 항목은 원본에서 확인할 수 있어요.</p></div><div><b>성취도</b><p>2026년 9월 공시, 2026학년도 1학기 자료입니다. 과목 평균과 A~E 분포를 보여주며, 학교 간 시험 난도와 수강 집단 차이가 있습니다.</p></div><div><b>졸업 후 진로</b><p>2025년 공시입니다. 국내 전문대·대학교, 국외, 취업, 기타를 구분합니다. 대학명·수시/정시·재수 여부는 이 자료에서 알 수 없습니다.</p></div></div><p class="legal">미추출 8개 문서를 복구했으며 스캔 표는 문자 인식했습니다. 원미고·정명고의 교육과정 핵심 요약은 편제표 원본과 대조했습니다. 문자 인식 본문에는 오탈자가 있을 수 있어 세부 수치는 원본을 확인하세요. 원문 저작권과 이용조건은 각 출처를 따릅니다.</p><p class="legal">설정·지망·메모·직접 입력한 통학시간은 이 브라우저에만 저장합니다. 통학 길찾기 버튼을 누르면 선택한 중학교와 고등학교의 공개 위치를 카카오맵으로 전달합니다. 집 주소는 입력받지 않습니다.</p><p class="sourcefoot">제작: 배움의 온도 진수학 · 자료별 공시·배포 기준은 각 출처 참고 · ${external('https://www.schoolinfo.go.kr/ng/go/pnnggo_a01_l0.do','학교알리미 자료 안내')}<br>핵심 공시자료는 공개 화면·첨부파일에서 수집했습니다. 앱은 교육청이나 개별 학교의 공식 서비스가 아닙니다.</p></div></div>`}
function openDetail(id,tab='overview'){detailSchool=Number(id);detailTab=tab;let s=school(id);$('#modalContent').innerHTML=`<div class="modalhead"><div class="row"><div><div class="badges"><span class="badge">${s.girls?'여학교':'남녀공학'} · ${esc(s.ownership)}</span></div><h2>${esc(short(s.name))}</h2><p>${esc(s.address)}</p></div><button class="iconbtn" data-close aria-label="학교 상세 닫기">×</button></div><div class="tabs" role="tablist" aria-label="학교 상세 항목">${[['overview','학교 안내'],['curriculum','과목·교육과정'],['assessment','평가계획'],['achievement','성취도'],['graduates','졸업 후 진로']].map(([k,t])=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'on':''}" data-tab="${k}">${t}</button>`).join('')}</div></div><div class="modalbody" id="detailBody"></div>`;renderDetail();if(!$('#modal').open)$('#modal').showModal()}
function renderDetail(){let s=school(detailSchool),body=$('#detailBody');if(detailTab==='overview'){let a=s.admissions.find(x=>x.year===2026);body.innerHTML=`<div class="three"><div class="metricbox"><small>2027 모집정원</small><strong>${s.quota}명</strong></div><div class="metricbox"><small>2026 모집정원</small><strong>${s.quota2026}명</strong></div><div class="metricbox"><small>2026 실제 입학생</small><strong>${a.total}명</strong></div></div><div class="panels" style="margin-top:20px"><div class="panel"><h2>매일의 통학을 확인하세요</h2><p>${origin()?`${esc(origin().name)} 기준 <b>${distanceText(s)}</b>`:'학교 찾기에서 다니는 중학교를 선택하면 직선거리를 볼 수 있습니다.'}</p><p class="hint">직선거리는 도로·횡단보도·버스 노선·대기시간을 반영하지 않습니다. 아래 대중교통 길찾기로 실제 경로를 확인하세요.</p>${external(route(s),'카카오맵 대중교통 길찾기','primary')}<div style="margin-top:20px" class="manualtime"><label for="travelTime">직접 확인한 편도 시간</label><input id="travelTime" type="number" min="1" max="300" inputmode="numeric" value="${esc(prefs.times[s.id]||'')}"><span>분</span><button class="outline small" id="saveTime">기록</button></div><p class="hint">통학시간은 사용자가 확인해 기록한 값입니다. 자동 계산값이 아닙니다.</p></div><div class="panel"><h2>어떤 자료를 볼까요?</h2><div class="doclist">${[['curriculum','배우는 과목'],['assessment','시험·수행평가 비율'],['achievement','과목별 성취도'],['graduates','졸업 후 진로']].map(([k,t])=>`<button class="doclink" data-tab="${k}">${t}<span>→</span></button>`).join('')}</div></div></div><div class="row actions"><button class="primary" data-add="${s.id}">${prefs.wishlist.includes(s.id)?'지망표에서 제외':'지망표에 추가'}</button><div>${external(s.source,'학교알리미')}${s.homepage?' · '+external(s.homepage,'학교 홈페이지'):''}</div></div><p class="sourcefoot">2027 모집정원은 경기도교육청 신입생 전형계획 24쪽 기준입니다. 2026 모집정원은 당시 안내 자료, 실제 입학생은 학교알리미 2026년 공시 기준이에요.</p>`}
else if(['curriculum','assessment'].includes(detailTab)){renderDocuments(s)}
else if(detailTab==='achievement'){body.innerHTML=`<div class="notice info">2026학년도 1학기 · 2026년 9월 공시. 학교별 시험 난도가 달라 평균·A비율만으로 학교 수준이나 내신 유불리를 단정할 수 없습니다.</div><div class="gradecontrol"><label for="grade">학년</label><select id="grade">${[1,2,3].map(n=>`<option value="${n}" ${grade===n?'selected':''}>${n}학년</option>`).join('')}</select><input id="subjectSearch" type="search" placeholder="과목명 검색" aria-label="성취도 과목 검색" value="${esc(subjectSearch)}"></div><div id="achievementTable"></div><p class="sourcefoot">평균: 점 / A~E: %. 3단계 성취도 과목의 D·E 공란은 0%를 뜻하지 않습니다. 이번 공시 표에는 표준편차가 제공되지 않습니다. ${external(s.source,'학교알리미 원문')}</p>`;renderAchievement(s)}
else if(detailTab==='graduates'){let g=graduate(s);body.innerHTML=`<div class="notice info">2025년 공시 졸업생 진로 현황입니다. 개별 대학명·수시/정시·재수 인원은 포함하지 않습니다.</div><div class="three"><div class="metricbox"><small>졸업자</small><strong>${g.graduates}명</strong></div><div class="metricbox"><small>대학교 진학률</small><strong>${rate(g.university,g.graduates)}</strong><p>전문대학 제외</p></div><div class="metricbox"><small>대학 진학률(전문대 포함)</small><strong>${rate(g.further_total,g.graduates)}</strong><p>국내 전문대·대학교 + 국외</p></div></div><div class="gradbar" aria-label="졸업생 진로 비율"><span style="width:${g.university/g.graduates*100}%"></span><span style="width:${(g.junior_college+g.foreign_total)/g.graduates*100}%"></span><span style="width:${(g.other+g.employed)/g.graduates*100}%"></span></div><div class="legend"><span><i style="background:#547d63"></i>국내 대학교</span><span><i style="background:#a3bb91"></i>전문대·국외</span><span><i style="background:#d8a071"></i>취업·기타</span></div><div class="tablewrap" style="margin-top:22px"><table><thead><tr><th>성별</th><th class="num">졸업자</th><th class="num">국내 전문대</th><th class="num">국내 대학교</th><th class="num">국외 계</th><th class="num">진학 계</th><th class="num">취업</th><th class="num">기타</th></tr></thead><tbody>${s.graduates.map(x=>`<tr><td>${x.gender}</td>${['graduates','junior_college','university','foreign_total','further_total','employed','other'].map(k=>`<td class="num">${x[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="sourcefoot">기타는 진학·취업 이외 인원이며 전원을 재수생으로 해석할 수 없습니다. 진학률 분모는 졸업자입니다. ${external(s.source,'학교알리미 원문')}</p>`}}
function renderAchievement(s){let rows=s.achievement.filter(x=>x.grade===grade&&x.subject.includes(subjectSearch));$('#achievementTable').innerHTML=`<p class="hint">${rows.length}개 과목 · 성취도 분포는 A부터 E 순서입니다.</p><div class="tablewrap"><table><thead><tr><th>과목(단위)</th><th class="num">평균</th><th>성취도 분포</th>${'ABCDE'.split('').map(k=>`<th class="num">${k}(%)</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.subject)}</td><td class="num">${x.mean.toFixed(1)}</td><td><div class="distbar" aria-label="${esc(x.subject)} 성취도 분포">${'ABCDE'.split('').map(k=>`<span style="width:${x[k]??0}%" title="${k}: ${x[k]??'미제공'}%"></span>`).join('')}</div></td>${'ABCDE'.split('').map(k=>`<td class="num">${x[k]===null||x[k]===undefined?'—':x[k].toFixed(1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="empty">조건에 맞는 과목이 없습니다.</p>':''}`}
function renderDocuments(s){let curriculum=detailTab==='curriculum',cat=curriculum?'교육과정':'평가계획',docs=s.documents.filter(x=>x.category===cat);if(docCategory!==cat||!docs.some(x=>x.id===docId)){docCategory=cat;docId=docs.find(x=>x.textUrl&&!/학업성적|협의록|학사일정/.test(x.title))?.id??docs[0]?.id;docQuery='';docPage=0}
let subj=[...new Set(s.achievement.filter(x=>x.grade>1).map(x=>x.subject.replace(/\s*\([\d.]+\)$/,'')))];$('#detailBody').innerHTML=`<div class="notice ${curriculum?'info':''}">${curriculum?'2026년 교육과정입니다. 2027학년도 입학생 확정 편제·선택 조건은 학교에 추가 확인이 필요합니다.':'2026년 2학기 평가계획입니다. 과목별 지필·수행 반영비율과 평가 영역을 원문에서 확인하세요.'}</div>${curriculum?`<h3 style="font-size:15px">실제 수업이 확인되는 과목</h3><p class="hint">2026년 1학기 2·3학년 성취도 공시에 등장하는 과목입니다. 2027학년도 신입생이 모두 선택할 수 있다는 뜻은 아닙니다.</p><div class="subjecttags">${subj.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:`<div class="chips"><button class="chip" data-docquery="지필평가">지필평가 찾기</button><button class="chip" data-docquery="수행평가">수행평가 찾기</button><button class="chip" data-docquery="반영">반영비율 찾기</button><button class="chip" data-docquery="평가 영역">평가 영역 찾기</button></div>`}<h3 style="font-size:16px;margin:20px 0 8px">공시 원문을 앱 안에서 읽기</h3><p class="hint">원문 표를 텍스트로 옮겨 열 정렬이 달라질 수 있습니다. 숫자의 대응이 모호하면 원본 첨부파일로 확인하세요.</p><div class="viewer-controls"><select id="docSelect" aria-label="${cat} 문서 선택">${docs.map(x=>`<option value="${x.id}" ${x.id===docId?'selected':''}>${esc(x.title)}</option>`).join('')}</select><input type="search" id="docSearch" placeholder="원문 전체 검색" aria-label="문서 내용 검색" value="${esc(docQuery)}"><button id="docSearchButton" class="secondary">찾기</button></div><div id="docStatus" class="hint"></div><div class="viewer" id="docText" tabindex="0">자료를 불러오고 있습니다…</div><div class="row" style="margin-top:10px"><button class="outline small" id="docPrev">이전 부분</button><small id="docPageLabel" class="muted"></small><button class="outline small" id="docNext">다음 부분</button></div><div id="docSource" class="sourcefoot"></div>`;loadDoc(s)}
async function loadDoc(s){let token=++docGeneration,d=s.documents.find(x=>x.id===docId);if(!d)return;$('#docStatus').textContent=`${d.period} · ${d.status}`;$('#docSource').innerHTML=external(d.url,'학교가 공시한 원본 파일')+' · '+external(s.source,'학교알리미');if(!d.textUrl){$('#docText').textContent='스캔 의심 부분이 있어 이 문서의 텍스트 추출을 중단했습니다. 원본은 직접 확인하실 수 있습니다.';$('#docPageLabel').textContent='본문 미추출';$('#docPrev').disabled=$('#docNext').disabled=true;return}try{if(!docCache.has(d.id)){let r=await fetch(d.textUrl);if(!r.ok)throw Error();docCache.set(d.id,await r.text())}if(token!==docGeneration||!$('#docText'))return;renderDocText(d)}catch{if(token===docGeneration&&$('#docText'))$('#docText').textContent='문서를 불러오지 못했습니다. 원본 파일을 확인하거나 다시 선택해 주세요.'}}
function renderDocText(d){let t=docCache.get(d.id)||'',chunk=14000;if(docQuery.trim()){let q=docQuery.trim(),hits=[];let pattern=[...q.replace(/\s/g,'')].map(c=>c.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('\\s*'),rx=new RegExp(pattern,'g'),m;while((m=rx.exec(t))&&hits.length<100){let pos=m.index,end=pos+m[0].length,before=t.slice(0,pos),pg=before.lastIndexOf('【');let page=pg>=0?before.slice(pg).match(/^【[^】]+】/)?.[0]||'':'본문';hits.push(`<b>${esc(page)}</b>\n${esc(t.slice(Math.max(0,pos-150),pos))}<mark>${esc(m[0])}</mark>${esc(t.slice(end,end+450))}`)}$('#docText').innerHTML=hits.length?hits.join('\n\n────────────────────────\n\n'):'검색어가 본문에 없습니다. 다른 표현으로 검색해 주세요.';$('#docPageLabel').textContent=`${hits.length===100?'최대 ':''}${hits.length}개 검색 결과`;$('#docPrev').disabled=$('#docNext').disabled=true}else{let pages=Math.ceil(t.length/chunk);docPage=Math.max(0,Math.min(docPage,pages-1));$('#docText').textContent=t.slice(docPage*chunk,(docPage+1)*chunk);$('#docPageLabel').textContent=`텍스트 ${docPage+1} / ${pages}부분`;$('#docPrev').disabled=docPage===0;$('#docNext').disabled=docPage>=pages-1}$('#docText').scrollTop=0}
function openCompare(){let ss=prefs.compare.map(school);if(ss.length<2){toast('학교를 2개 이상 선택해 주세요.');return}detailSchool=null;$('#modalContent').innerHTML=`<div class="modalhead"><div class="row"><div><p class="eyebrow">SIDE BY SIDE</p><h2>학교 나란히 보기</h2><p>같은 기준으로 비교하고, 선택의 이유를 찾아보세요.</p></div><button class="iconbtn" data-close aria-label="비교 닫기">×</button></div></div><div class="modalbody"><div class="tablewrap"><table class="comparetbl"><thead><tr><th>비교 기준</th>${ss.map(s=>`<th>${esc(short(s.name))}</th>`).join('')}</tr></thead><tbody>${[
['학교 구분',s=>`${s.girls?'여학교':'남녀공학'} · ${esc(s.ownership)}`],['중학교 기준 직선거리',s=>distanceText(s)],['직접 확인한 편도 시간',s=>prefs.times[s.id]?`${esc(prefs.times[s.id])}분`:'아직 입력하지 않음'],['2026 모집정원',s=>s.quota2026+'명'],['2027 모집정원',s=>`<span class="metric">${s.quota}</span>명`],['2026 모집 대비',s=>`${s.quota-s.quota2026>0?'+':''}${s.quota-s.quota2026}명`],['2026 실제 입학생',s=>s.admissions.find(x=>x.year===2026).total+'명'],['2025 대학교 진학률',s=>{let g=graduate(s);return rate(g.university,g.graduates)+'<br><small>전문대학 제외 / 졸업자 분모</small>'}],['2025 대학 진학률(전문대 포함)',s=>{let g=graduate(s);return rate(g.further_total,g.graduates)}],['교육과정 확인',s=>s.scanFiles?'선택과목 추가 확인 필요':'2026 편제·선택 관련 본문 확인'],['관심 과목·평가 방식',s=>`<button class="inline-link" data-detail="${s.id}" data-detailtab="curriculum">학교 자료 열기 →</button>`]
].map(([label,fn])=>`<tr><td>${label}</td>${ss.map(s=>`<td>${fn(s)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">진학률은 학생 구성과 졸업 후 선택의 차이를 포함합니다. 학교 순위나 교육의 질을 직접 나타내는 지표가 아닙니다. 2027 편제와 실제 통학시간은 따로 확인하세요.</div></div>`;if(!$('#modal').open)$('#modal').showModal()}
function download(name,text,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){let rows=[['참고용 지망표','2027학년도 부천 일반고','공식 원서 아님'],['학생 성별',prefs.gender==='male'?'남학생':'여학생'],['출발 기준',prefs.origin||'미설정'],['순위','학교','직선거리(km)','직접 확인한 통학시간(분)','선택 이유']];prefs.wishlist.forEach((id,i)=>{let s=school(id);rows.push([i+1,s.name,prefs.distance?dist(s)?.toFixed(2)||'':'',prefs.times[id]||'',prefs.notes[id]||''])});const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('2027_부천_나의지망표.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;
if(b.dataset.view||b.dataset.go){setView(b.dataset.view||b.dataset.go);renderSim();return}
if(b.hasAttribute('data-close')){$('#modal').close();docGeneration++;return}
if(b.dataset.gender){prefs.gender=b.dataset.gender;prefs.wishlist=prefs.wishlist.filter(id=>eligible(school(id)));prefs.compare=prefs.compare.filter(id=>eligible(school(id)));render();return}
if(b.dataset.interest){let k=b.dataset.interest;prefs.interests=prefs.interests.includes(k)?prefs.interests.filter(x=>x!==k):[...prefs.interests,k];render();return}
if(b.dataset.add!==undefined){toggleAdd(Number(b.dataset.add));return}
if(b.dataset.detail!==undefined){openDetail(Number(b.dataset.detail),b.dataset.detailtab||'overview');return}
if(b.dataset.tab){detailTab=b.dataset.tab;$$('[data-tab]').forEach(t=>{t.classList.toggle('on',t.dataset.tab===detailTab);t.setAttribute('aria-selected',t.dataset.tab===detailTab)});renderDetail();return}
if(b.dataset.remove!==undefined){prefs.wishlist=prefs.wishlist.filter(x=>x!==Number(b.dataset.remove));render();return}
if(b.dataset.move){let [id,dir]=b.dataset.move.split(',').map(Number),i=prefs.wishlist.indexOf(id),j=i+dir;if(j>=0&&j<prefs.wishlist.length)[prefs.wishlist[i],prefs.wishlist[j]]=[prefs.wishlist[j],prefs.wishlist[i]];render();return}
if(b.dataset.docquery){docQuery=b.dataset.docquery;$('#docSearch').value=docQuery;docPage=0;loadDoc(school(detailSchool));return}
switch(b.id){case 'sourcesBtn':setView('guide');break;case 'compareOpen':openCompare();break;case 'compareClear':prefs.compare=[];$$('[data-compare]').forEach(x=>x.checked=false);save();compareBar();break;case 'fillRemaining':data.schools.filter(eligible).forEach(s=>{if(!prefs.wishlist.includes(s.id))prefs.wishlist.push(s.id)});render();toast('남은 학교를 이름순으로 추가했습니다. 순서를 검토해 주세요.');break;case 'downloadList':exportCSV();break;case 'printList':window.print();break;case 'backup':download('부천고교_지망표_백업.json',JSON.stringify({version:1,...prefs},null,2),'application/json');break;case 'restore':$('#importFile').click();break;case 'resetSim':simMale=simFemale=100;simSplit=50;render();renderSim();break;case 'saveTime':{let v=Number($('#travelTime').value);if($('#travelTime').value==='' ){delete prefs.times[detailSchool];save();toast('통학시간 기록을 비웠습니다.');break}if(!Number.isFinite(v)||v<1||v>300){toast('1~300분 사이로 입력해 주세요.');break}prefs.times[detailSchool]=Math.round(v);save();toast('직접 확인한 통학시간을 기록했습니다.');break}case 'docSearchButton':docQuery=$('#docSearch').value;docPage=0;loadDoc(school(detailSchool));break;case 'docPrev':docPage--;loadDoc(school(detailSchool));break;case 'docNext':docPage++;loadDoc(school(detailSchool));break;}
});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='origin'){prefs.origin=t.value;render()}else if(t.id==='distance'){prefs.distance=t.checked;if(!t.checked&&prefs.schoolSort==='distance')prefs.schoolSort='name';render()}else if(t.id==='schoolSort'){if(t.value==='distance'&&(!prefs.distance||!origin())){toast('출발 중학교와 거리 표시를 먼저 선택해 주세요.');t.value=prefs.schoolSort;return}prefs.schoolSort=t.value;render()}else if(t.dataset.compare!==undefined){let id=Number(t.dataset.compare);if(t.checked){if(prefs.compare.length>=4){toast('최대 4개교까지 비교할 수 있습니다.');t.checked=false;return}prefs.compare.push(id)}else prefs.compare=prefs.compare.filter(x=>x!==id);save();compareBar()}else if(t.id==='grade'){grade=Number(t.value);renderAchievement(school(detailSchool))}else if(t.id==='docSelect'){docId=Number(t.value);docPage=0;loadDoc(school(detailSchool))}});
document.addEventListener('input',e=>{let t=e.target;if(t.dataset.note!==undefined){prefs.notes[t.dataset.note]=t.value;save()}if(t.id==='schoolSearch'){let pos=t.selectionStart;query=t.value;render();$('#schoolSearch').focus();$('#schoolSearch').setSelectionRange(pos,pos)}if(t.id==='subjectSearch'){subjectSearch=t.value;renderAchievement(school(detailSchool))}if(['simMale','simFemale','simSplit'].includes(t.id)){if(t.id==='simMale')simMale=Number(t.value);if(t.id==='simFemale')simFemale=Number(t.value);if(t.id==='simSplit')simSplit=Number(t.value);renderSim()}});
document.addEventListener('keydown',e=>{if(e.target.id==='docSearch'&&e.key==='Enter'){$('#docSearchButton').click()}});
let dragId=null;document.addEventListener('dragstart',e=>{let item=e.target.closest('[data-rank]');if(item){dragId=Number(item.dataset.rank);e.dataTransfer.effectAllowed='move'}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-rank]'))e.preventDefault()});document.addEventListener('drop',e=>{let item=e.target.closest('[data-rank]');if(!item||dragId===null)return;e.preventDefault();let target=Number(item.dataset.rank),a=prefs.wishlist.indexOf(dragId),b=prefs.wishlist.indexOf(target);if(a>=0&&b>=0){prefs.wishlist.splice(a,1);prefs.wishlist.splice(b,0,dragId);render()}dragId=null});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){$('#modal').close();docGeneration++}});
$('#importFile').addEventListener('change',async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error();let p=JSON.parse(await file.text());if(p.version!==1||!['male','female'].includes(p.gender)||!Array.isArray(p.wishlist)||!p.wishlist.every(id=>Number.isInteger(id)&&school(id)))throw Error();prefs={...defaults,gender:p.gender,origin:data.middles.some(m=>m.name===p.origin)?p.origin:'',distance:typeof p.distance==='boolean'?p.distance:true,wishlist:[...new Set(p.wishlist)].filter(id=>p.gender!=='male'||!school(id).girls),interests:Array.isArray(p.interests)?p.interests.filter(x=>['commute','curriculum','assessment','achievement','graduates'].includes(x)):defaults.interests,notes:{},times:{},compare:[]};for(let s of data.schools){if(typeof p.notes?.[s.id]==='string')prefs.notes[s.id]=p.notes[s.id].slice(0,3000);let tm=Number(p.times?.[s.id]);if(tm>=1&&tm<=300)prefs.times[s.id]=Math.round(tm)}save();render();toast('백업 기록을 불러왔습니다.')}catch{toast('올바른 나침반 백업 파일인지 확인해 주세요.')}e.target.value=''});
fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;prefs.wishlist=Array.isArray(prefs.wishlist)?prefs.wishlist.filter(id=>school(id)&&eligible(school(id))):[];prefs.compare=Array.isArray(prefs.compare)?prefs.compare.filter(id=>school(id)&&eligible(school(id))).slice(0,4):[];view=['schools','wishlist','demand','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'schools';render();renderSim()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>자료를 불러오지 못했습니다.</h1><p>잠시 후 페이지를 새로고침해 주세요.</p></div>'});
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(['schools','wishlist','demand','guide'].includes(v)&&v!==view){view=v;render();renderSim()}});
